CREATE OR REPLACE FUNCTION private.ru4b_public_floor_reason(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v text := btrim(coalesce(p_text,''));
begin
  if v = '' then return 'EMPTY_CONTENT'; end if;
  if v ~* '[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}' then return 'EMAIL_NOT_PUBLIC'; end if;
  if v ~* '(https?://|www\.)' then return 'OFF_PLATFORM_LINK_NOT_PUBLIC'; end if;
  if v ~* '(^|[[:space:]])@[A-Z0-9_.]{2,}' then return 'SOCIAL_HANDLE_NOT_PUBLIC'; end if;
  -- PKG-029c (deep read 12.5): a phone number starts like one (0, 00, + or 381) and holds 8 to 13 digits; a date
  -- ("01.10.2026") and a price range ("15000 - 20000") are not phone numbers.
  if exists (select 1 from regexp_matches(v, '(\+?[0-9][0-9 ()/.\-]{6,}[0-9])', 'g') m
              where regexp_replace(m[1], '[^0-9+]', '', 'g') ~ '^(\+|00|0|381)'
                and length(regexp_replace(m[1], '[^0-9]', '', 'g')) between 8 and 13
                and m[1] !~ '^[0-9]{1,2}[./][0-9]{1,2}[./][0-9]{2,4}') then return 'PHONE_NOT_PUBLIC'; end if;
  return null;
end;
$function$
